// 📊 COLLECTEUR - Préserve les données du webhook
const webhookData = $input.item;

console.log('📊 WEBHOOK REÇU:');
console.log('- JSON keys:', webhookData.json ? Object.keys(webhookData.json) : 'null');
console.log('- Binary keys:', webhookData.binary ? Object.keys(webhookData.binary) : 'null');
console.log('- Body contenu:', webhookData.json?.body?.contenu?.substring(0, 100));

// Préserver toutes les données webhook
const result = {
  json: {
    webhook_data: webhookData.json,
    contenu_original: webhookData.json?.body?.contenu || 'Pas de contenu',
    subtitle_original: webhookData.json?.body?.subtitle || '',
    timestamp: new Date().toISOString()
  },
  binary: webhookData.binary || {}
};

console.log('✅ DONNÉES PRÉSERVÉES:', {
  contenu_length: result.json.contenu_original.length,
  binary_count: Object.keys(result.binary).length
});

return result;

// 🔗 FUSION FINALE - Combine collector + OpenAI
const collectorData = $input.first();
const openAIData = $input.last();

console.log('🔗 FUSION:');
console.log('- Collector:', !!collectorData);
console.log('- OpenAI:', !!openAIData);

// Récupérer les données IA
let aiTitle = 'Titre par défaut';
let aiSubtitle = 'Sous-titre par défaut';
let aiBody = collectorData?.json?.contenu_original || 'Corps par défaut';

if (openAIData?.json && Array.isArray(openAIData.json)) {
  const aiContent = openAIData.json[0]?.message?.content;
  if (aiContent) {
    try {
      const cleaned = aiContent.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsed = JSON.parse(cleaned);

      aiTitle = parsed.title || aiTitle;
      aiSubtitle = parsed.subtitle || aiSubtitle;
      aiBody = parsed.body || aiBody;

      console.log('✅ IA PARSÉE:', { title: aiTitle, subtitle: aiSubtitle });
    } catch (e) {
      console.log('❌ Erreur parsing IA:', e.message);
    }
  }
}

// Fusionner tout
const result = {
  json: {
    // Données originales
    contenu_original: collectorData?.json?.contenu_original,
    subtitle_original: collectorData?.json?.subtitle_original,

    // Données IA
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,

    // Debug
    debug: {
      collector_found: !!collectorData,
      openai_found: !!openAIData,
      ai_parsed: aiTitle !== 'Titre par défaut',
      binary_count: collectorData?.binary ? Object.keys(collectorData.binary).length : 0
    }
  },
  binary: collectorData?.binary || {}
};

console.log('🎯 FUSION TERMINÉE:', result.json.debug);

return result;

// ✅ RÉSULTAT FINAL
const flaskResult = $input.item.json;
const fusionData = $input.first();

if (flaskResult?.success) {
  return {
    json: {
      status: 'success',
      project_id: flaskResult.project_id,
      download_url: `http://host.docker.internal:5003/api/download/${flaskResult.project_id}`,
      message: '🎉 Document InDesign créé !',
      ai_analysis: {
        title: fusionData?.json?.ai_title,
        subtitle: fusionData?.json?.ai_subtitle,
        body_preview: fusionData?.json?.ai_body?.substring(0, 100) + '...'
      },
      debug: fusionData?.json?.debug
    }
  };
}

return {
  json: {
    status: 'error',
    error: flaskResult?.error || 'Erreur Flask',
    debug: { flask_result: flaskResult, fusion_data: fusionData?.json }
  }
};
